import json,pathlib,collections,ast
import s24_learning_probe as x
r=x.RUN;e=x.e;p=e.read(r/'protocol.json');s=e.read(r/'state.json');v=e.read(r/'review.json');model=e.read(r/'model_rule.json');choices=e.read(r/'choices_before_target_execution.json');coverage=e.read(r/'rule_coverage_zero_api.json')
rows=[];totals={}
def cost(u):return (u['prompt_tokens']*.3+u['completion_tokens']*1.2)/1e6
for z in s['rows']:
 rev=next(t for t in v['rows'] if t['key']==z['key']);u=z['response']['usage'];artifact=e.read(r/(z['key']+'.artifact.json'));(r/(z['key']+'.py')).write_text(artifact['code'])
 rows.append(dict(key=z['key'],task_id=z['task_id'],arm=z['arm'],public=f"{z['public_result']['tests_passed']}/{z['public_result']['tests_run']}",sealed=f"{rev['sealed']['tests_passed']}/{rev['sealed']['tests_run']}",strict=rev['strict_pass'],tokens=u['total_tokens'],estimated_usd=cost(u),finish_reason=z['response']['finish_reason']))
for a in ['P','CP']:
 z=[r for r in rows if r['arm']==a];totals[a]=dict(tokens=sum(v['tokens'] for v in z),estimated_usd=sum(v['estimated_usd'] for v in z),strict_success=sum(v['strict'] for v in z))
u=s['induction']['usage'];learn=dict(tokens=u['total_tokens'],estimated_usd=cost(u));summary=dict(rows=rows,totals=totals,learning=learn,total_tokens=learn['tokens']+sum(v['tokens'] for v in totals.values()),total_estimated_usd=learn['estimated_usd']+sum(v['estimated_usd'] for v in totals.values()),actual_invoice=None,budget=v['budget'],policy_targets=len(choices),policy_overrides=sum(z['selected']=='CP' for z in choices),policy_is_separate_sampled_arm=False,new_operator_registry_entries=0,model_calls=5,rule=model,choices=choices)
e.save(r/'summary.json',summary)
