ledger=[json.loads(t) for t in (r/'budget.jsonl').read_text().splitlines()];ids=[z['payload']['request_id'] for z in ledger if z['kind']=='RESERVED' and z['payload']['kind']=='model'];assert len(ids)==len(set(ids))==5
wire=p['induction_request']['wire'];assert all(t['packet']['task_id'] not in e.canonical(wire) for t in p['targets'])
assert e.sha(x.__file__)==p['source_dependencies']['scripts/s24_learning_probe.py'];e.verify()
e.save(r/'integrity.json',dict(unique_real_requests=len(ids),unknown=v['budget']['unknown_or_pending_requests'],old_protocol_unchanged=True,induction_contains_target_ids=False,registry_writes=0,sources='Only S23 public outcomes; final review is not in induction evidence'))
lines=['# S24：自动归纳上下文算子条件与跨程序探索','', '结论：`RULE_INDUCTION_FEASIBLE / TARGET_REUSE_NOT_OBSERVED / NO_INCREMENTAL_BENEFIT`。真实模型从S23的一正一反公开证据归纳出可执行条件，但两道预先冻结目标均不匹配；固定整理操作在两题上也未产生成功增益。没有修改阈值、追加候选、追加模型调用或写入注册表。','', '## 这次实际做了什么','', '1. 从已有S20-G公开记录中有限筛查其他原题。原题/阶段排序，每题最早检查点，排除S22原题，最多20题；实际16题。可解析且无图片占位的6题中，事先挑两道注释较多、两道较少的候选。筛查的只读重建保存在screening_reconstruction.json，精确目标及wire在API前冻结。','2. 按题面写输入合法性检查器，不包含求解算法。四道候选中两道存在越界测试而排除，不按新模型表现替换。最终为test-549和r0704。两道来源S23公开输入也通过检查。','3. 将S23公开失败、各干预公开结果与成本交给模型，只调用一次，生成条件及操作选择。不提供目标任务、目标结果或最终封存答案。','4. 在模型选择冻结后，每目标运行P和Always-CP各一次。已学策略使用事前选中的分支结果作描述性重放，不另运行一个随机第三组。','5. 在线锁定后执行同题封存复核；再只读审查规则覆盖机会，不修改本轮任务集合。','', '## 人工能力与自动学习的边界','', '人工提供：输入合法性检查器、去注释并格式重建的宿主操作、固定交付提醒、可用条件字段及安全解释器。模型学习：机制假设、适用状态、数值门槛，以及KEEP/STRIP_COMMENTS选择。模型未编写新的代码变换算法，不能声称自主发现了全新算子类别。', '本轮没有改生产生成器、Controller、代际规则或旧算子权限。策略只保存在实验制品中，标记NO_ROUTING_PERMISSION；不是Experimental算子。源实验的成功属于人工CP干预，不能倒算为本轮自动算子的真实来源修复。','', '## 真实生成的条件','', '```text\n公开状态 = WRONG_ANSWER\n且旧代码字符数 >= 8000\n且注释字符占比 >= 0.50\n    → 整理旧代码上下文 + 固定交付提醒\n否则\n    → 原上下文 + 相同固定交付提醒\n```','', '模型明确表示：门槛只是区分当前两个来源点，只有一个正例和一个失败例，不能证明因果或泛化。其假设全文和原始响应分别见model_rule.json、induction.raw.json。格式及权限契约首次通过，未修订。','', '|目标|代码字符|注释占比|冻结选择|','|---|---:|---:|---|']
for z in choices:lines.append(f"|{z['task_id']}|{z['features']['code_chars']}|{z['features']['comment_ratio']:.2%}|{z['selected']}|")
lines+=['','两次选择都等于P：0次新增动作、0次不同请求。策略没有在这两个目标上实际使用上下文整理。不得把共享的P分支称为第三组独立样本，也不能把其输出差异归因于学习。','', '## 固定P与CP的真实结果','', '|分支|公开|封存|严格成功|Token|估算费用|','|---|---:|---:|---|---:|---:|']
for z in rows:lines.append(f"|{z['key']} {z['task_id']}|{z['public']}|{z['sealed']}|{z['strict']}|{z['tokens']}|${z['estimated_usd']:.7f}|")
lines+=['', 'test-549的两组去注释AST相同：仍将行访问次数混同于具体座位访问，剩余问题没有按每行m名学生处理；这是具体求解逻辑未改变。r0704两组均漏算两个自身平衡括号串组成的一对，公开样例`2 / (()) / ()`实际输出0而预期1。虽然封存12/12，通过不了公开全集仍判失败。','', 'P与CP均0/2严格成功。CP少用Token，但两者都失败，不能称可靠效率收益。每分支只运行一次，本轮也不建立稳定效果估计。','', '## 数据质量实验','', '|候选|非法公开输入|具体问题|处理|','|---|---:|---|---|','|r0493|4/14|安全岛坐标大于道路n|本轮整题排除|','|r2804|6/14|查询k超过当前题面10^9|本轮整题排除|','|test-549|0/16|通过当前题面语法及范围检查|保留|','|r0704|0/15|通过当前题面语法及范围检查|保留|','', 'S23的两道来源公开输入也通过本轮范围核查。目标封存输入由评价侧独立检查，各12个均通过，答案未进入学习/求解请求。合法性检查不能单独证明所有标准答案正确；沿用既有评分依据，并明确这一限制。被排除两题没有调用模型，没有将其非法错误用于此次归纳。', '这不是全数据集污染率估计，仅是4道候选的有限审查。没有追溯改动S19/S20/S22历史结果，也未读取119题确认池。', '', '## 未修改规则的覆盖诊断','', f"在既有S20-G记录中排除S22原题后，{len(coverage['rows'])}个可解析事件（{coverage['unique_tasks']}道原题）有{coverage['matches']}次规则匹配，涉及4道原题；其中r1290含图片占位，另外为r1959的l2a/l2b、r1225的l3、r0329的l2a。", '这些是后续阶段的新匹配机会，不是本轮预注册的目标，也没有产生真实干预或收益证据。它们的输入合法性、剩余预算与wire尚未完成全部验收。因此不能直接把5次匹配算作5次可执行复用，更不能因此调整阈值或追加本轮API。','', '## 成本、工程验收及保留记录','', f"共5次真实响应：归纳1次、目标求解4次。总Token {summary['total_tokens']}；峰值缓存未命中口径估算${summary['total_estimated_usd']:.7f}（其中归纳{learn['tokens']} Token / ${learn['estimated_usd']:.7f}）；保守账本占用${v['budget']['charged_or_reserved_cost_microusd']/1e6:.6f}，硬上限$0.25。实际账单未知，UNKNOWN为0，无重复请求。", f"正式运行工具{v['budget']['tool_calls']}单元、工具计时{v['budget']['charged_or_reserved_tool_milliseconds']/1000:.3f}秒；另有零API Worker验收账本。工具时间不是完整容器/CPU成本，未货币化。若将S23作为学习来源，应额外列示此前8次探针的29,245 Token和约$0.0125598开发成本，不能主张此处新费用已经涵盖所有研发摊销。", '5项新测试通过（权限越界拒绝、类型拒绝、目标选择、非法输入拒绝、完整mock及防重复），并完成真实Worker的31个公开输入原始/整理后行为一致验收。首次预检因Colima停止而失败，发送模型之前恢复原实例后重验；不是UNKNOWN请求重发，记录见preflight_initial_failure.json。', '模型与价格复核依据：[DeepSeek官方价格页](https://api-docs.deepseek.com/quick_start/pricing/)。使用deepseek-flash、thinking disabled、temperature 0，输出8192、输入上界32768，未扩大预算。单次、温度0仍不保证确定性。','', '## 对下一步的具体判断','', '已经验证“真实公开失败与干预证据 → 模型生成条件计划 → 严格验证 → 目标前冻结路由选择”可以运行；尚未验证自动策略真实介入后的独立价值。', '当前不应继续降低0.5或8000门槛来凑触发。最小后续实验应从上面三个无图片的自然匹配原题中，按固定顺序核查输入与预算，选最早可信匹配检查点，再比较P和固定CP；同时用未匹配任务检查误干预。保持当前模型规则冻结，并始终保留Always-CP基线。', '如果固定CP在匹配与不匹配状态都同样好，改成基础工作流工具即可，不宣称条件学习必要。只有真实历史证据帮助区分“用/不用”且带来可复核差异，才支持失败驱动条件算子的独立价值。', '本轮不支持扩展419题长流、不支持老年代晋级，也不否定此机制总体价值。重点发现是：数据可信性要先于学习；可生成条件不等于条件有用；未命中与负迁移必须分开。']
(r/'S24_自动条件归纳与跨程序探索报告.md').write_text('\n'.join(lines)+'\n');print(json.dumps(summary,ensure_ascii=False,indent=2)[:3600])
